// ---- Shared helpers for this page (prefix vm). Data: window.VM_DATA (20_js_vm_0data.js, generated by runs/make_data.py) ----
window.VM=(function(){
  const D=window.VM_DATA||{};
  const $=id=>document.getElementById(id);
  const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const comma=n=>{const s=String(Math.round(n));return s.replace(/\B(?=(\d{3})+(?!\d))/g,',')};
  const fix=(x,d)=>Number(x).toFixed(d);
  const pct=(x,d)=>(x*100).toFixed(d==null?0:d)+'%';
  const css=n=>getComputedStyle(document.body).getPropertyValue(n).trim()||'#888';
  const onRender=(f,tab)=>{tab=tab||'t-read';(window.TAB_RENDER=window.TAB_RENDER||{});(window.TAB_RENDER[tab]=window.TAB_RENDER[tab]||[]).push(f)};
  const width=el=>{const w=el&&el.clientWidth;return w&&w>40?w:Math.max(280,Math.min(860,(document.documentElement.clientWidth||900)-60))};
  // a crisp canvas of CSS width w and height h inside el
  function canvas(el,w,h){let c=el.querySelector('canvas');if(!c){c=document.createElement('canvas');el.appendChild(c)}
    const r=window.devicePixelRatio||1;c.width=Math.round(w*r);c.height=Math.round(h*r);c.style.width=w+'px';c.style.height=h+'px';
    const g=c.getContext('2d');g.setTransform(r,0,0,r,0,0);g.clearRect(0,0,w,h);g.font='11px system-ui,-apple-system,Segoe UI,sans-serif';g.textBaseline='middle';return {c,g}}
  // segmented buttons: opts [[value,label],...]; cb(value)
  function seg(el,opts,cur,cb){el.innerHTML=opts.map(o=>'<button data-v="'+esc(o[0])+'" class="'+(o[0]===cur?'on':'')+'">'+o[1]+'</button>').join('');
    el.onclick=e=>{const b=e.target.closest('button');if(!b)return;el.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));cb(b.dataset.v)}}
  const imgCache={};
  function img(uri,cb){if(!uri){cb(null);return}if(imgCache[uri]&&imgCache[uri].complete){cb(imgCache[uri]);return}
    const im=imgCache[uri]||new Image();imgCache[uri]=im;if(!im.src)im.src=uri;if(im.complete)cb(im);else im.addEventListener('load',()=>cb(im),{once:true})}
  // text blocks computed from data: elements with data-vm="key" get TXT[key]
  const TXT={};
  function fill(root){(root||document).querySelectorAll('[data-vm]').forEach(el=>{const k=el.dataset.vm;if(k in TXT)el.innerHTML=TXT[k]})}
  const tag={meas:'<span class="meas">measured</span>',pub:'<span class="pub">paper</span>',vend:'<span class="vend">vendor</span>',der:'<span class="der">derived</span>'};
  // colour ramp for ratios (1 = neutral, high = hot)
  function heat(t){t=Math.max(0,Math.min(1,t));const a=[[245,245,240],[250,200,90],[220,80,40],[140,20,20]];
    const x=t*(a.length-1),i=Math.min(a.length-2,Math.floor(x)),f=x-i,c=a[i].map((v,k)=>Math.round(v+(a[i+1][k]-v)*f));return 'rgb('+c.join(',')+')'}
  return {D,$,esc,comma,fix,pct,css,onRender,width,canvas,seg,img,TXT,fill,tag,heat};
})();
